<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script>
<script>
const labels=@json($text),listUrl=@json(route('elasticsearch-monitoring.data-streams.data')),detailBase=@json(route('elasticsearch-monitoring.data-streams.details',['name'=>'__NAME__']));
const body=document.getElementById('streams'),modal=new bootstrap.Modal(document.getElementById('detailsModal'));let allStreams=[];
const number=v=>Number(v||0).toLocaleString(),bytes=v=>{let n=Number(v||0);return n>=1073741824?(n/1073741824).toFixed(2)+' GB':n>=1048576?(n/1048576).toFixed(2)+' MB':n>=1024?(n/1024).toFixed(2)+' KB':n+' B';};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
function render(){const q=document.getElementById('search').value.toLowerCase(),items=allStreams.filter(x=>x.name.toLowerCase().includes(q));document.getElementById('stream-count').textContent=number(allStreams.length);if(!items.length){body.innerHTML='<tr><td colspan="9" class="text-center text-secondary py-5">'+labels.empty+'</td></tr>';return;}body.innerHTML=items.map(x=>'<tr><td class="ps-3"><a href="#" class="stream-name" data-stream="'+encodeURIComponent(x.name)+'">'+esc(x.name)+'</a></td><td>'+esc(x.status)+'</td><td>'+number(x.generation)+'</td><td>'+number(x.backing_indices_count)+'</td><td class="text-end">'+number(x.documents_count)+'</td><td class="text-end">'+bytes(x.storage_bytes)+'</td><td>'+esc(x.ilm_policy||labels.na)+'</td><td>'+esc(x.template||labels.na)+'</td><td class="text-end pe-3"><button class="btn btn-sm btn-outline-primary" data-stream="'+encodeURIComponent(x.name)+'">'+labels.details+'</button></td></tr>').join('');}
async function load(){body.innerHTML='<tr><td colspan="9" class="text-center text-secondary py-5">'+labels.loading+'</td></tr>';try{const r=await fetch(listUrl,{headers:{Accept:'application/json'}}),d=await r.json();if(!r.ok)throw new Error(d.error||labels.error);allStreams=d.data_streams||[];render();}catch(e){body.innerHTML='<tr><td colspan="9" class="text-center text-danger py-5">'+esc(e.message||labels.error)+'</td></tr>';}}
function summary(label,value){const col=document.createElement('div');col.className='col-12 col-md-6 col-xl-3';const card=document.createElement('div');card.className='border rounded-3 p-3 h-100 bg-light';const h=document.createElement('div');h.className='small text-secondary mb-1';h.textContent=label;const v=document.createElement('div');v.className='fw-semibold text-break';v.textContent=value===null||value===undefined||value===''?labels.na:String(value);card.append(h,v);col.append(card);document.getElementById('summary').append(col);}
async function details(name){document.getElementById('modalTitle').textContent=name;document.getElementById('modalSubtitle').textContent=labels.loading;document.getElementById('summary').replaceChildren();document.getElementById('backing-rows').innerHTML='<tr><td colspan="6">'+labels.loading+'</td></tr>';document.getElementById('raw-json').textContent='';modal.show();try{const r=await fetch(detailBase.replace('__NAME__',encodeURIComponent(name)),{headers:{Accept:'application/json'}}),d=await r.json();if(!r.ok)throw new Error(d.error||labels.error);const s=d.data_stream;document.getElementById('modalSubtitle').textContent=s.ilm_policy||labels.na;[[labels.status,s.status],[labels.generation,s.generation],[labels.template,s.template],[labels.policy,s.ilm_policy],[labels.prefer,s.prefer_ilm?'Yes':'No'],[labels.next,s.next_generation_managed_by],[labels.hidden,s.hidden?'Yes':'No'],[labels.system,s.system?'Yes':'No'],[labels.routing,s.allow_custom_routing?'Yes':'No'],[labels.replicated,s.replicated?'Yes':'No'],[labels.rollover,s.rollover_on_write?'Yes':'No']].forEach(([k,v])=>summary(k,v));const a=s.backing_indices||[];document.getElementById('backing-rows').innerHTML=a.length?a.map(i=>'<tr><td class="text-break">'+esc(i.name)+'</td><td class="small text-break">'+esc(i.uuid||labels.na)+'</td><td>'+esc(i.lifecycle_phase||labels.na)+'</td><td>'+esc(i.lifecycle_policy||labels.na)+'</td><td class="text-end">'+number(i.documents_count)+'</td><td class="text-end">'+bytes(i.storage_bytes)+'</td></tr>').join(''):'<tr><td colspan="6">'+labels.empty+'</td></tr>';document.getElementById('raw-json').textContent=JSON.stringify(s,null,2);}catch(e){document.getElementById('modalSubtitle').textContent=e.message;document.getElementById('backing-rows').innerHTML='<tr><td colspan="6" class="text-danger">'+esc(e.message)+'</td></tr>';}}
body.addEventListener('click',e=>{const t=e.target.closest('[data-stream]');if(t){e.preventDefault();details(decodeURIComponent(t.dataset.stream));}});document.getElementById('reload').addEventListener('click',load);document.getElementById('search').addEventListener('input',render);load();
</script></body></html>
